  ('venice', $j$[{"ko":"산마르코 광장","en":"St. Mark's Square"},{"ko":"대운하·리알토 다리","en":"Grand Canal & Rialto Bridge"},{"ko":"두칼레 궁전","en":"Doge's Palace"},{"ko":"무라노·부라노 섬","en":"Murano & Burano"},{"ko":"곤돌라","en":"Gondola ride"},{"ko":"탄식의 다리","en":"Bridge of Sighs"}]$j$, $j${"ko":"2박 3일","en":"2 nights"}$j$, $j${"ko":"4월~6월, 9월~10월","en":"Apr–Jun, Sep–Oct"}$j$, $j$[{"key":"coffee","min":4.2,"max":null},{"key":"taxi","min":9.5,"max":9.5,"label":{"ko":"수상버스(바포레토) 1회권","en":"Vaporetto single ticket"}},{"key":"meal","label":{"ko":"치케티·트라토리아 한 끼","en":"Cicchetti / trattoria meal"},"min":15,"max":28}]$j$),
