  ('warsaw', $j$[{"ko":"구시가 광장","en":"Old Town Market Square"},{"ko":"왕궁","en":"Royal Castle"},{"ko":"쇼팽 박물관","en":"Chopin Museum"},{"ko":"와지엔키 공원","en":"Łazienki Park"},{"ko":"문화과학궁전","en":"Palace of Culture and Science"},{"ko":"바르샤바 봉기 박물관","en":"Warsaw Uprising Museum"}]$j$, $j${"ko":"2박 3일","en":"2 nights"}$j$, $j${"ko":"5월~9월","en":"May–Sep"}$j$, $j$[{"key":"coffee","min":17,"max":null},{"key":"taxi","min":20,"max":40},{"key":"meal","label":{"ko":"피에로기·밀크바 한 끼","en":"Pierogi / milk bar meal"},"min":25,"max":45}]$j$),
  ('yeosu', $j$[{"ko":"여수 밤바다·낭만포차","en":"Yeosu night sea & pocha"},{"ko":"오동도","en":"Odongdo Island"},{"ko":"돌산대교·돌산공원","en":"Dolsan Bridge & Park"},{"ko":"해상 케이블카","en":"Yeosu Cable Car"},{"ko":"향일암","en":"Hyangiram"},{"ko":"이순신광장","en":"Yi Sun-sin Square"}]$j$, $j${"ko":"1박 2일","en":"1 night"}$j$, $j${"ko":"4월~6월, 9월~11월","en":"Apr–Jun, Sep–Nov"}$j$, $j$[{"key":"coffee","min":4500,"max":null},{"key":"taxi","min":4800,"max":8000},{"key":"meal","label":{"ko":"게장·갓김치 정식 한 끼","en":"Gejang / gat-kimchi set"},"min":12000,"max":20000}]$j$),
  ('zanzibar', $j$[{"ko":"스톤 타운","en":"Stone Town"},{"ko":"능귀·카덴게 해변","en":"Nungwi & Kendwa beaches"},{"ko":"프리즌 아일랜드","en":"Prison Island"},{"ko":"스파이스 투어","en":"Spice tour"},{"ko":"조단 숲(붉은 콜로부스)","en":"Jozani Forest (red colobus)"},{"ko":"다우선 선셋 크루즈","en":"Dhow sunset cruise"}]$j$, $j${"ko":"4박 5일","en":"4–5 nights"}$j$, $j${"ko":"6월~10월, 12월~2월","en":"Jun–Oct, Dec–Feb"}$j$, $j$[{"key":"coffee","min":8000,"max":null},{"key":"taxi","min":20000,"max":40000},{"key":"meal","label":{"ko":"로컬 식당 한 끼","en":"Local restaurant meal"},"min":10000,"max":25000}]$j$),
  ('zurich', $j$[{"ko":"취리히 호수","en":"Lake Zurich"},{"ko":"구시가지(니더도르프)","en":"Niederdorf Old Town"},{"ko":"그로스뮌스터","en":"Grossmünster"},{"ko":"반호프슈트라세","en":"Bahnhofstrasse"},{"ko":"유틀리베르크 전망대","en":"Uetliberg"},{"ko":"린트 초콜릿 박물관","en":"Lindt Home of Chocolate"}]$j$, $j${"ko":"2박 3일","en":"2 nights"}$j$, $j${"ko":"5월~9월","en":"May–Sep"}$j$, $j$[{"key":"coffee","min":5.2,"max":null},{"key":"taxi","min":15,"max":25},{"key":"meal","label":{"ko":"런치 메뉴 한 끼","en":"Lunch menu"},"min":20,"max":30}]$j$)
) as v(slug, landmarks, trip_length, best_season, prices)
join public.destinations d on d.slug = v.slug
on conflict (destination_id) do update
set landmarks = excluded.landmarks,
    trip_length = excluded.trip_length,
    best_season = excluded.best_season,
    prices = excluded.prices,
    updated_at = now();
